--------------------------------------------------------
--  DDL for Trigger TR_FM_CUSTOMER_MASTER
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "FAKHRUDDINERP"."TR_FM_CUSTOMER_MASTER" 
BEFORE UPDATE OF NAME ON FM_CUSTOMER_MASTER FOR  EACH ROW
DECLARE 
V_ID NUMBER DEFAULT 0;
BEGIN

IF :OLD.NAME <> :NEW.NAME THEN
    SELECT ACCOUNT_ID INTO V_ID 
    FROM (
    SELECT NVL(MAX(ACCOUNT_ID),0) ACCOUNT_ID FROM FM_ACCOUNT_LEDGER WHERE CUST_TYPE='CUSTOMER' AND ACCOUNT_ID = :NEW.ID
    );
    
    IF V_ID <> 0 THEN 
    
    RAISE_APPLICATION_ERROR(-20999,'Customer already have Financial Records posted.');
    
    END IF;
END IF;
  
  
END;
/
ALTER TRIGGER "FAKHRUDDINERP"."TR_FM_CUSTOMER_MASTER" ENABLE;
